const contacts = $input.all().map(i => i.json);
if (!contacts.length || !contacts[0].id) return [{ json: { no_data: true } }];

// K-means-like clustering (simplified)
const segments = {
  'high_value_engaged': { contacts: [], criteria: 'High LTV + High engagement' },
  'hot_prospects': { contacts: [], criteria: 'High score + Recent activity + No purchase yet' },
  'nurture_needed': { contacts: [], criteria: 'Medium score + Low recent engagement' },
  'at_risk_customers': { contacts: [], criteria: 'Customer + Declining engagement' },
  'new_cold': { contacts: [], criteria: 'New + Low engagement' },
  'power_users': { contacts: [], criteria: 'High activity + Multiple interactions' }
};

for (const c of contacts) {
  const score = parseInt(c.lead_score) || 0;
  const activities = parseInt(c.total_activities) || 0;
  const opens = parseInt(c.emails_opened) || 0;
  const clicks = parseInt(c.emails_clicked) || 0;
  const meetings = parseInt(c.meetings) || 0;
  const ltv = parseFloat(c.lifetime_value) || 0;
  const isCustomer = c.lead_status === 'customer';
  const daysSinceCreated = (Date.now() - new Date(c.created_at).getTime()) / (1000*60*60*24);

  let segment = 'new_cold';

  if (isCustomer && ltv > 0 && activities > 10) {
    segment = 'high_value_engaged';
  } else if (isCustomer && activities < 5) {
    segment = 'at_risk_customers';
  } else if (activities > 15 && (clicks > 5 || meetings > 0)) {
    segment = 'power_users';
  } else if (score >= 60 && !isCustomer && activities > 5) {
    segment = 'hot_prospects';
  } else if (score >= 30 && score < 60 && opens < 3) {
    segment = 'nurture_needed';
  } else if (daysSinceCreated < 30 && activities < 3) {
    segment = 'new_cold';
  }

  segments[segment].contacts.push(c.id);
}

// Build summary
const summary = Object.entries(segments).map(([name, data]) => ({
  segment: name,
  count: data.contacts.length,
  criteria: data.criteria,
  contact_ids: data.contacts.slice(0, 50)
}));

return [{ json: {
  total_segmented: contacts.length,
  segments: summary,
  generated_at: new Date().toISOString()
}}];

